window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["constrained-decoding"]={"title":"约束解码：用自动机把非法 token 概率置零","subtitle":"从 JSON Schema、文法状态和 tokenizer 边界，到死路、复杂度、流式输出与语义校验。","thesis":"约束解码把 schema、正则或文法编译成状态机，在每一步只允许仍能到达接受状态的 token。它可以保证<b>生成结果属于指定形式语言</b>，却不能保证字段真实、跨字段业务关系成立、用户有权执行动作。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"状态 q₃","rule":"schema 只允许 refund 或 ask","steps":".30/.45=.667","interpretation":"只证明动作名称合法"}}],"formulas":[{"id":"constrained-decoding-renormalization","section":3,"formulaIndex":1,"symbols":[{"name":"P","meaning":"模型原始或受限 token 概率","evidence":"模型给 token t 的原始概率"},{"name":"t","meaning":"当前被评估的候选 token","evidence":"token t 的原始概率"},{"name":"s","meaning":"当前文法解析状态","evidence":"解析状态 s"},{"name":"M","meaning":"仍可通向合法结果的 token 集","evidence":"仍能通向完整合法结果的 token 集"},{"name":"u","meaning":"遍历整个词表的候选索引","evidence":"u 遍历所有词表候选"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"约束解码在每步采样时把不符合形式规则的 token 概率置零。","evidence":"约束解码输入模型 logits、当前前缀和形式规则"},"problem":{"answer":"它解决只靠提示要求 JSON 仍会以小概率产生坏格式的问题。","evidence":"百万次调用仍会稳定出现坏格式"},"inputOutput":{"answer":"输入 logits、前缀和规则，输出只从合法 token 集产生的序列。","evidence":"输出只从合法 token 集抽样的序列"},"mechanism":{"answer":"约束器删除非法候选并对剩余概率重新归一化。","evidence":"把非法候选概率置零并重新归一化"},"interpretation":{"answer":"格式通过只表示结果属于指定形式语言。","evidence":"只说明结果属于形式语言"},"boundary":{"answer":"它不保证字段真实、业务关系成立或调用者有权限。","evidence":"不证明字段真实、业务关系成立或调用者有权限"}},{"section":2,"definition":{"answer":"增量状态机记录文法前缀所处位置及下一步合法 token。","evidence":"文法怎样变成增量状态"},"problem":{"answer":"它解决模型每次只生成一个 token 时如何判断前缀仍可完成的问题。","evidence":"下一 token 合不合法"},"inputOutput":{"answer":"输入 schema、文法和 tokenizer，输出解析状态与合法 token 集。","evidence":"输出可随前缀推进的解析状态及合法 token 集"},"mechanism":{"answer":"每接受完整 token 字节串推进状态，只有接受态可结束。","evidence":"每接受一个完整 token 字节串就更新状态"},"interpretation":{"answer":"允许当前 token 表示前缀仍可继续，只有接受态才能正常结束。","evidence":"只有接受态才可结束"},"boundary":{"answer":"不支持的 schema 关键字和开放世界事实须生成后验证。","evidence":"必须留给生成后校验"}},{"section":3,"definition":{"answer":"受限分布是原概率经合法集合掩码并重新归一化后的概率。","evidence":"掩码后必须重新归一化"},"problem":{"answer":"它说明模型最偏好非法 token 时合法候选概率怎样变化。","evidence":"受限分布怎样变化"},"inputOutput":{"answer":"输入原概率和合法集合，输出非法为零且合法总和为一的分布。","evidence":"输出非法项为零且合法项总和为一的新分布"},"mechanism":{"answer":"先用指示函数掩码，再除以剩余合法概率质量。","evidence":"先掩码再在合法集归一化"},"interpretation":{"answer":"合法高概率候选少时，受限输出的内容质量仍可能下降。","evidence":"合法输出也可能内容很差"},"boundary":{"answer":"空合法集应诊断 schema、tokenizer、前缀或顺序不兼容。","evidence":"应返回可诊断失败"}},{"section":4,"definition":{"answer":"退款示例展示枚举约束如何删除 delete 并重算 refund 与 ask。","evidence":"一步退款动作怎样被约束"},"problem":{"answer":"它解释模型偏好非法动作时如何保证只生成 schema 允许值。","evidence":"模型偏好 delete"},"inputOutput":{"answer":"输入状态 q₃、候选概率与枚举，输出两个合法动作的新概率。","evidence":"输出 refund 与 ask 的重归一化分布"},"mechanism":{"answer":"删除 delete 和其他项，用 0.45 合法质量归一化剩余候选。","evidence":"合法质量 0.45 作为分母"},"interpretation":{"answer":"refund 的 0.667 是受限抽样概率，不是退款资格概率。","evidence":"refund 为 0.667"},"boundary":{"answer":"资格、金额和权限仍必须由外部业务与鉴权系统校验。","evidence":"退款资格、金额和权限仍需外部校验"}},{"section":5,"definition":{"answer":"tokenizer 感知掩码判断整个 token 字节串能否推进到可继续状态。","evidence":"token 不是字符，掩码必须理解 tokenizer"},"problem":{"answer":"它避免按首字符过滤而误删跨字符 token 或合法枚举前缀。","evidence":"按“下一个字符是否合法”过滤 token 会错"},"inputOutput":{"answer":"输入解析状态与完整 token 字节串，输出该 token 是否可继续。","evidence":"输出能否走到可继续状态"},"mechanism":{"answer":"模拟整个 token 通过解析器，并保留仍可完成枚举的前缀。","evidence":"合法枚举前缀也应保留"},"interpretation":{"answer":"token 表面相似不能替代对完整字节和后续可达性的判断。","evidence":"token 可跨字符、引号、逗号与 Unicode 字节"},"boundary":{"answer":"更换模型或 tokenizer 后必须重新编译，不能复用旧掩码。","evidence":"旧缓存可能封死合法路径或放行错误"}},{"section":6,"definition":{"answer":"schema 复杂度由枚举、递归、交叉分支和正则共同扩大状态空间。","evidence":"复杂 schema 会制造状态与性能问题"},"problem":{"answer":"它解释字段分支增加为何拖慢首次编译和逐 token 掩码。","evidence":"首 token 可能更慢、解码也更抖"},"inputOutput":{"answer":"输入 schema、tokenizer 和资源限额，输出状态数、成本与拒绝原因。","evidence":"输出编译状态数、逐步掩码成本与拒绝原因"},"mechanism":{"answer":"编译文法并缓存状态，运行时为每个前缀计算合法集合。","evidence":"大枚举、递归和交叉分支扩大状态空间"},"interpretation":{"answer":"首 token 慢常反映编译，每 token 慢常反映合法集计算。","evidence":"首次文法编译"},"boundary":{"answer":"缓存键必须含 schema 哈希和 tokenizer 版本，并限制资源规模。","evidence":"缓存键必须同时包含 schema 哈希与 tokenizer 版本"}},{"section":7,"definition":{"answer":"流式提交边界规定只有完整接受态并通过校验后才能执行工具。","evidence":"流式输出和工具调用的提交边界"},"problem":{"answer":"它防止把仍可继续或已截断的合法前缀误当成完整参数执行。","evidence":"能否边生成边执行字段"},"inputOutput":{"answer":"输入前缀、接受态、schema 和授权，输出原子工具调用。","evidence":"输出仅在全部校验完成后的原子工具调用"},"mechanism":{"answer":"等待接受态，完成 schema 与业务校验，再以幂等键提交。","evidence":"重试必须带幂等键"},"interpretation":{"answer":"前缀合法仅表示仍可完成，不表示对象已经完整。","evidence":"前缀合法不等于对象完整"},"boundary":{"answer":"断流 JSON 不能自动补齐后执行，外部文本仍需注入隔离。","evidence":"不能自动补齐截断 JSON 后执行"}},{"section":8,"definition":{"answer":"约束解码验收分开测语法、schema、业务、事实、权限和任务结果。","evidence":"格式、模式、业务和权限要分别评测"},"problem":{"answer":"它防止 JSON 有效率百分百掩盖内容错误或越权动作。","evidence":"团队还应该看哪些数"},"inputOutput":{"answer":"输入输出、schema、事实、主体和工具反馈，输出六层质量指标。","evidence":"输出语法、模式、业务、事实、授权与任务质量指标"},"mechanism":{"answer":"解析器、schema、规则、数据库和执行层按顺序逐关验证。","evidence":"解析成功只是第一关"},"interpretation":{"answer":"格式成功不能补偿后续业务或权限关卡失败。","evidence":"不能被格式有效率补偿"},"boundary":{"answer":"高风险动作还需幂等、越权拦截和故障回归。","evidence":"高风险动作还要验证幂等和越权拦截"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>解释状态机与 token 掩码；手算一步受限概率；识别 tokenizer/文法死路；设计语法、语义和权限三层验证。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>提示要求与解码保证的区别<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">“只返回 JSON”写得再醒目，为什么百万次调用仍会稳定出现坏格式？</p><p>约束解码输入模型 logits、当前前缀和形式规则，输出只从合法 token 集抽样的序列。提示仅改变概率，约束器则把非法候选概率置零并重新归一化；格式通过只说明结果属于形式语言，不证明字段真实、业务关系成立或调用者有权限。</p><p>提示只改变模型分布，合法输出概率即使是 99.9%，百万次仍预期约一千次失败。约束解码在采样器层面删除非法候选，使输出不能离开文法；这是机制保证，不是模型“更听话”。</p><p>它适合工具参数、批量抽取和数据库接口。自由文章若强行套复杂 schema，会牺牲表达、增加延迟；而且结构合法并不使内容可信。</p><div class=\"dd-note\"><b>三层边界：</b>约束解码保形式；业务校验保字段关系；鉴权与事务控制保动作后果。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>文法怎样变成增量状态<span class=\"dd-badge eng\">机制</span></h2><p class=\"dd-lead\">生成只看到一个前缀，系统怎样知道下一 token 合不合法？</p><p>状态编译输入 schema、正则或文法和目标 tokenizer，输出可随前缀推进的解析状态及合法 token 集。每接受一个完整 token 字节串就更新状态，只有接受态可以正常结束；不支持的 schema 关键字和开放世界事实必须留给生成后校验。</p><p>运行时把 JSON Schema、正则或上下文无关文法编译成 DFA、PDA 或等价解析状态。状态保存当前在对象、数组、字符串还是数字，哪些必填字段已出现，以及下一步允许什么。每接受一个 token，就推进状态；只有接受态才可结束。</p><p>JSON Schema 不只是一份说明。支持器需把类型、枚举、required、additionalProperties、数组界限与嵌套引用映射为文法；并非每个实现支持所有关键字，远程引用、复杂正则和语义格式通常需生成后校验。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>约束来源</th><th>容易表达</th><th>通常表达不了</th></tr></thead><tbody><tr><td>正则</td><td>局部字符串形状</td><td>任意嵌套与跨字段关系</td></tr><tr><td>JSON Schema</td><td>对象、类型、枚举、必填</td><td>数据库存在性与权限</td></tr><tr><td>CFG</td><td>递归语法、代码结构</td><td>变量语义与运行结果</td></tr><tr><td>自定义状态机</td><td>协议和有限流程</td><td>开放世界事实</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>掩码后必须重新归一化<span class=\"dd-badge math\">数学</span></h2><p class=\"dd-lead\">原模型最想输出非法 token 时，受限分布怎样变化？</p><p>受限采样输入原概率与当前合法集合，输出非法项为零且合法项总和为一的新分布。先掩码再在合法集归一化；若高概率候选全非法，合法输出也可能内容很差。空集合表示 schema、tokenizer、前缀或处理顺序不兼容，应返回可诊断失败。</p><div class=\"dd-formula\" data-formula-id=\"constrained-decoding-renormalization\"><math display=\"block\" aria-label=\"状态 s 下 token t 的受限概率 P prime 等于原概率乘合法集合指示函数，再除以所有候选 u 的合法概率质量之和\"><mrow><msup><mi>P</mi><mo>′</mo></msup><mo>(</mo><mi>t</mi><mo>∣</mo><mi>s</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mi>P</mi><mo>(</mo><mi>t</mi><mo>∣</mo><mi>s</mi><mo>)</mo><mn>1</mn><mo>[</mo><mi>t</mi><mo>∈</mo><mi>M</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>]</mo></mrow><mrow><munder><mo>∑</mo><mi>u</mi></munder><mi>P</mi><mo>(</mo><mi>u</mi><mo>∣</mo><mi>s</mi><mo>)</mo><mn>1</mn><mo>[</mo><mi>u</mi><mo>∈</mo><mi>M</mi><mo>(</mo><mi>s</mi><mo>)</mo><mo>]</mo></mrow></mfrac></mrow></math></div><p class=\"dd-formula-note\"><code>P(t|s)</code> 是解析状态 s 下模型给 token t 的原始概率，<code>P′(t|s)</code> 是应用文法约束后的抽样概率；<code>M(s)</code> 是从状态 s 仍能通向完整合法结果的 token 集；<code>1[·]</code> 是条件成立取 1、否则取 0 的指示函数；<code>u</code> 遍历所有词表候选。分母是剩余合法概率质量，负责把合法候选重新归一化到总和为 1。</p><p>M(s) 是当前状态仍能通向完整合法结果的 token 集。非法 token 乘零，剩余质量重新归一化。约束不会让模型更懂任务；若所有高概率候选非法，它只能在低概率合法候选中选择，内容质量可能下降。</p><p>温度、top-k、top-p 与掩码的顺序会影响结果。通常先得到 logits，再应用语法掩码并在合法集上采样；若先 top-k 恰好删光合法 token，会形成错误死路。实现应明确顺序并回归。</p><div class=\"dd-note warn\"><b>空候选不是“再试一次”就好。</b>　它常说明 schema、tokenizer、前缀或裁剪顺序不兼容，应返回可诊断状态。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：一步退款动作怎样被约束<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">前缀是 {\"action\": 时，模型偏好 delete，schema 只允许 refund 或 ask，发生什么？</p><p>案例输入状态 q₃、候选概率和枚举约束，输出 refund 与 ask 的重归一化分布。delete 的 0.50 被置零，合法质量 0.45 作为分母，因此 refund 为 0.667、ask 为 0.333；这只证明动作名称合法，退款资格、金额和权限仍需外部校验。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"JSON 状态机对退款动作候选 token 掩码并重新归一化\"><defs><marker id=\"cd1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"83\" width=\"150\" height=\"76\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"93\" y=\"108\" text-anchor=\"middle\" class=\"svg-t\">状态 q₃</text><text x=\"93\" y=\"130\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">前缀 {“action”:</text><text x=\"93\" y=\"149\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">期待枚举字符串</text><path d=\"M168,121 L235,121\" stroke=\"#6b7484\" marker-end=\"url(#cd1)\"/><rect x=\"237\" y=\"38\" width=\"175\" height=\"166\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"324\" y=\"62\" text-anchor=\"middle\" class=\"svg-t\">原始候选概率</text><text x=\"324\" y=\"90\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">“delete” .50 → 非法×0</text><text x=\"324\" y=\"116\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">“refund” .30 → 保留</text><text x=\"324\" y=\"142\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">“ask” .15 → 保留</text><text x=\"324\" y=\"168\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">其他 .05 → 非法×0</text><text x=\"324\" y=\"190\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">合法质量=.45</text><path d=\"M412,121 L479,121\" stroke=\"#6b7484\" marker-end=\"url(#cd1)\"/><rect x=\"481\" y=\"64\" width=\"200\" height=\"114\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"581\" y=\"90\" text-anchor=\"middle\" class=\"svg-t\">重新归一化</text><text x=\"581\" y=\"118\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">P′(refund)=.30/.45=.667</text><text x=\"581\" y=\"143\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">P′(ask)=.15/.45=.333</text><text x=\"581\" y=\"165\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">delete 不可能生成</text></svg><figcaption>图 1　约束改变可采样集合，却没有证明 refund 真实合格或已授权。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>原概率</th><th>文法允许</th><th>受限概率</th><th>业务上是否安全</th></tr></thead><tbody><tr><td>delete</td><td>.50</td><td>否</td><td>0</td><td>未讨论</td></tr><tr><td>refund</td><td>.30</td><td>是</td><td>.667</td><td>仍需资格、金额、权限</td></tr><tr><td>ask</td><td>.15</td><td>是</td><td>.333</td><td>仍需问题必要且不索取多余隐私</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>token 不是字符，掩码必须理解 tokenizer<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">为什么按“下一个字符是否合法”过滤 token 会错？</p><p>tokenizer 感知掩码输入当前解析状态和候选 token 的完整字节串，输出能否走到可继续状态。token 可跨字符、引号、逗号与 Unicode 字节，合法枚举前缀也应保留；换模型或 tokenizer 后必须重新编译，旧缓存可能封死合法路径或放行错误。</p><p>一个 token 可能包含开引号、多个字符甚至引号和逗号；Unicode 字符可能跨字节，转义序列又改变表面文本。运行时要判断整个 token 字节串从当前解析状态走过后是否合法，并能否继续到接受态，而不是只看 token 首字符。</p><p>枚举“refund”可能被切成一个 token，也可能是 <code>ref</code>+<code>und</code>。前缀 token 即使尚未组成完整枚举，只要仍是某个合法枚举的前缀就应允许；反之，表面以 r 开头却无法完成任何枚举就应屏蔽。</p><div class=\"dd-note warn\"><b>必须用目标模型的真实 tokenizer 编译和测试。</b>　换模型或 tokenizer 后复用旧掩码缓存，可能允许错误或把合法路径封死。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>复杂 schema 会制造状态与性能问题<span class=\"dd-badge eng\">复杂度</span></h2><p class=\"dd-lead\">字段和分支越完整，为什么首 token 可能更慢、解码也更抖？</p><p>复杂度治理输入 schema 结构、tokenizer 和资源上限，输出编译状态数、逐步掩码成本与拒绝原因。大枚举、递归和交叉分支扩大状态空间；最小 schema 加版本缓存通常更稳，但缓存键必须同时包含 schema 哈希与 tokenizer 版本。</p><p>大枚举、深递归、oneOf/anyOf 交叉和复杂正则会增加编译时间、状态集合与每步合法 token 计算。可缓存“schema 哈希 + tokenizer 版本”的编译产物，但必须限制 schema 大小、递归深度、数组长度和字符串长度，防止资源耗尽。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>症状</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td>首 token 很慢</td><td>首次文法编译</td><td>预编译与版本缓存</td></tr><tr><td>每 token 慢</td><td>合法集合计算复杂</td><td>简化分支、状态缓存</td></tr><tr><td>空候选</td><td>实现不支持或前缀冲突</td><td>兼容性测试、明确失败</td></tr><tr><td>输出过长</td><td>无数组/字符串上限</td><td>schema 与总 token 双限</td></tr></tbody></table></div><p>最小 schema 往往更稳：只让模型生成需要判断的字段，服务器补默认值和派生字段。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>流式输出和工具调用的提交边界<span class=\"dd-badge eng\">工程</span></h2><p class=\"dd-lead\">既然每个前缀都可延伸为合法结果，能否边生成边执行字段？</p><p>流式提交输入增量前缀、接受态、schema 结果和业务授权，输出仅在全部校验完成后的原子工具调用。前缀合法不等于对象完整，断流也可能留下半个值；重试必须带幂等键，不能自动补齐截断 JSON 后执行。</p><p>不能把“当前前缀合法”当“对象已完整”。字符串、数字、数组都可能继续；网络中断还会留下半个对象。客户端可流式展示进度，但工具参数应等接受态、schema 和业务校验全部通过后原子提交。</p><p>流断后要区分取消、超时和正常结束，不能自动把截断 JSON 补齐后执行。重试复用幂等键，避免第一次其实成功、响应丢失后重复退款。敏感自由文本字段仍需内容检查和注入隔离。</p><div class=\"dd-note warn\"><b>约束只限制模型输出。</b>　schema 描述中的恶意文本、检索内容和工具返回仍是外部不可信输入。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>格式、模式、业务和权限要分别评测<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">JSON 有效率 100% 后，团队还应该看哪些数？</p><p>分层评测输入生成结果、schema、权威事实、主体权限和工具反馈，输出语法、模式、业务、事实、授权与任务质量指标。解析成功只是第一关；任何后续关卡失败都不能被格式有效率补偿，高风险动作还要验证幂等和越权拦截。</p><p>分别记录语法有效率、schema 通过率、死路率、额外 TTFT/TPOT、业务校验通过率、事实正确率、工具成功率、越权拦截和最终任务质量。只报 parse 成功会让“格式全对、内容全错”看起来完美。</p><ol class=\"dd-steps\"><li>解析器验证形式和完整结束。</li><li>schema 验证字段、类型、枚举、范围。</li><li>确定性规则验证金额、日期、跨字段不变量。</li><li>数据库/证据验证实体存在与事实。</li><li>执行层根据当前主体重新鉴权并限制副作用。</li><li>失败返回结构化原因，有限重试或转人工。</li></ol><p>用 Unicode、转义、极深嵌套、空数组、长枚举、断流和不支持关键字做对抗回归。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">约束解码是形式语言工具，不是事实验证器、业务规则引擎或权限系统。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>提示写“仅 JSON”就是保证</td><td>仍是概率行为，约束需在解码层实施</td></tr><tr><td>合法 JSON 就符合 schema</td><td>语法只保括号引号，schema 还管字段类型</td></tr><tr><td>符合 schema 就能执行</td><td>仍需事实、业务、鉴权与幂等校验</td></tr><tr><td>字符合法即可筛 token</td><td>token 可跨字符和语法边界</td></tr><tr><td>schema 越复杂越可靠</td><td>会增加状态、延迟、兼容与死路风险</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>tokenization、logits、采样参数、自动机/文法</td></tr><tr><td><b>本页核心</b></td><td>状态编译、合法 token 集、归一化、死路与接受态</td></tr><tr><td>接口</td><td>结构化输出、工具调用、流式输出</td></tr><tr><td>安全</td><td>guardrails、权限、工作流幂等和应用评测</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>将最小 schema 编译为 tokenizer 感知状态机</li><li>逐 token 计算合法集合并掩码</li><li>在合法候选中重新归一化采样</li><li>只在接受态提交完整对象</li><li>做 schema/业务/事实/权限验证</li><li>记录死路与有限恢复并回归</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>约束解码比提示要求多了什么保证？</li><li>示例中 refund 的受限概率为何是 .667？</li><li>为什么要使用真实 tokenizer？</li><li>接受态前能否执行工具？</li><li>结构合法还缺哪些检查？</li><li>假设“约束解码：用自动机把非法 token 概率置零”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“约束解码：用自动机把非法 token 概率置零”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>在采样层把非法 token 概率置零，使结果不能离开形式语言。</li><li>合法质量为 .30+.15=.45，重新归一化 .30/.45。</li><li>token 可跨多个字符和语法边界，字符级判断会错。</li><li>不能，前缀仍可能继续或截断，需完整校验后原子提交。</li><li>schema 支持范围、业务不变量、事实存在性、鉴权和副作用控制。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2109.05093\" target=\"_blank\" rel=\"noopener\">PICARD</a>：增量解析拒绝非法 token</li><li><a href=\"https://arxiv.org/abs/2212.06094\" target=\"_blank\" rel=\"noopener\">LMQL</a>：约束语言模型查询与解码</li><li><a href=\"https://arxiv.org/abs/2501.10868\" target=\"_blank\" rel=\"noopener\">JSONSchemaBench</a>：JSON Schema 约束覆盖、效率和质量</li><li><a href=\"https://github.com/dottxt-ai/outlines\" target=\"_blank\" rel=\"noopener\">Outlines</a>：基于有限状态方法的结构化生成实践</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
